import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
exps = {}
for i in range(1, 6):
    fname = f"experiment_{i}_csv"
    try:
        exps[i] = pd.read_csv(eval(fname))
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(exps[i].columns)}")
        print(f"Shape: {exps[i].shape}")
        print(exps[i].describe().round(2))

        # Check what interventions were applied
        for col in exps[i].columns:
            if 'diuretic' in col.lower() or 'dose' in col.lower() or 'titration' in col.lower():
                print(f"Diuretic/dose column '{col}': unique values = {exps[i][col].unique()[:5]}")
                break
        else:
            print("No diuretic column found - likely observation only")

    except Exception as e:
        print(f"Could not load experiment {i}: {e}")
